def wiggle_max_length(nums):
    if len(nums) < 2:
        return len(nums)
    up = down = 1
    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            up = down + 1                    # extend the best downswing-ending sequence
        elif nums[i] < nums[i - 1]:
            down = up + 1                      # extend the best upswing-ending sequence
    return max(up, down)

