public class Main {
    static int wiggleMaxLength(int[] nums) {
        if (nums.length < 2) return nums.length;
        int up = 1, down = 1;
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] > nums[i - 1]) up = down + 1;         // extend the best downswing-ending sequence
            else if (nums[i] < nums[i - 1]) down = up + 1;      // extend the best upswing-ending sequence
        }
        return Math.max(up, down);
    }
}

